draw(rightanglemark(B,D,A,10));
label("$A$",A,NW);
label("$B$",B,SW);
label("$C$",C,SE);
label("$D$",D,NE);
label("6",(A+B)/2,W);
label("8",(B+C)/2,S);
[/asy]

